    async def fetch_permissions(self, params={}) -> List[str]:
        rights = ['reading']
        try:
            await self.cancel_order('12345', 'BTC/USDT')
            return rights
        except Exception as e:
            txt = str(e).lower()
            if txt.find('incorrect apikey') >= 0:
                raise AuthenticationError(self.id + ' ' + str(e))
            if isinstance(e, AuthenticationError):
                if txt.find('permission') >= 0 or txt.find('denied') >= 0:
                    return rights
                raise e
            if isinstance(e, ExchangeError):
                if txt.find('permission') >= 0 or txt.find('denied') >= 0:
                    return rights
                rights.append('spotTrading')
                rights.append('marginTrading')
                rights.append('futuresTrading')
                return rights
            raise e

